const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-6.2603, 53.3498]).buffer(15000); // 15km buffer around Dublin
  const date_1984 = ee.DateRange('1984-11-01', '1984-11-30');
  const date_2022 = ee.DateRange('2022-11-01', '2022-11-30');

  // Function to mask clouds in Landsat SR data
  const cloudMaskL457 = function(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
    return image.updateMask(cloud.not());
  };

  // Function to calculate built-up area from an image
  // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
  // Positive NDBI is considered built-up.
  const calculateBuiltUpArea = function(image, swirBand, nirBand) {
    const ndbi = image.normalizedDifference([swirBand, nirBand]).rename('NDBI');
    const isBuiltUp = ndbi.gt(0); // Simple threshold for built-up
    const areaImage = isBuiltUp.multiply(ee.Image.pixelArea());
    const area = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 300,
      maxPixels: 1e9
    });
    return ee.Number(area.get('NDBI')).divide(1e6); // Return area in sq km
  };

  // 2. Data Acquisition & Processing
  // --- 1984 ---
  let collection1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR')
    .filterBounds(aoi)
    .filterDate(date_1984);

  // If no images in Nov, try the whole year as a fallback
  if (collection1984.size().getInfo() === 0) {
    collection1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR')
        .filterBounds(aoi)
        .filterDate('1984-01-01', '1984-12-31');
  }

  const imageCount1984 = collection1984.size().getInfo();
  let area1984 = null;

  if (imageCount1984 > 0) {
    const image1984 = collection1984.map(cloudMaskL457).median();
    area1984 = calculateBuiltUpArea(image1984, 'SR_B5', 'SR_B4').getInfo();
  }

  // --- 2022 ---
  const collection2022 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2') // Landsat 9 is most recent
    .filterBounds(aoi)
    .filterDate(date_2022)
    .map(cloudMaskL457);

  const imageCount2022 = collection2022.size().getInfo();
  let area2022 = null;

  if (imageCount2022 > 0) {
    const image2022 = collection2022.median();
    area2022 = calculateBuiltUpArea(image2022, 'SR_B6', 'SR_B5').getInfo();
  }

  // 3. Validation & Final Answer
  console.log(`1984 Image Count: ${imageCount1984}`);
  console.log(`2022 Image Count: ${imageCount2022}`);

  if (imageCount1984 === 0 || imageCount2022 === 0) {
    console.log("Evidence: No images found for one or both periods.");
    console.log("A: Yes");
  } else if (area1984 === null || area2022 === null) {
    console.log("Evidence: Calculation failed, likely due to no valid pixels after cloud masking.");
    console.log("C2: No Valid Pixels");
  } else {
    console.log(`1984 Estimated Built-up Area (km²): ${area1984.toFixed(2)}`);
    console.log(`2022 Estimated Built-up Area (km²): ${area2022.toFixed(2)}`);
    const increase = area2022 > area1984;
    console.log(`Built-up area increased: ${increase}`);
    if (increase) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
